PRAGMA foreign_keys=OFF;
BEGIN;
CREATE TABLE IF NOT EXISTS users_new(id INTEGER PRIMARY KEY AUTOINCREMENT,role TEXT NOT NULL CHECK(role IN('admin','teacher','student','parent')),username TEXT NOT NULL UNIQUE,name TEXT NOT NULL,pass_hash TEXT NOT NULL,level TEXT,must_change INTEGER NOT NULL DEFAULT 0,fails INTEGER NOT NULL DEFAULT 0,locked_until INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','disabled')),created_by INTEGER,created_at INTEGER NOT NULL,approved_at INTEGER);
INSERT INTO users_new SELECT id,role,username,name,pass_hash,level,must_change,fails,locked_until,status,created_by,created_at,approved_at FROM users;
DROP TABLE users;
ALTER TABLE users_new RENAME TO users;
CREATE INDEX IF NOT EXISTS ix_users_status ON users(status);
ALTER TABLE tests ADD COLUMN story_id INTEGER;
ALTER TABLE tests ADD COLUMN time_limit_min INTEGER;
ALTER TABLE tests ADD COLUMN due_at INTEGER;
ALTER TABLE tests ADD COLUMN updated_at INTEGER;
ALTER TABLE tests ADD COLUMN archived INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS stories(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,level TEXT NOT NULL,story TEXT NOT NULL,summary TEXT,setting TEXT,time_period TEXT,characters TEXT,events TEXT,lesson TEXT,author TEXT,language TEXT DEFAULT 'English',licence TEXT,source_name TEXT,source_url TEXT,tags TEXT,cover_path TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),created_by INTEGER REFERENCES users(id),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS classes(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,level TEXT NOT NULL,academic_year TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(name,academic_year));
CREATE TABLE IF NOT EXISTS class_members(id INTEGER PRIMARY KEY AUTOINCREMENT,class_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,member_role TEXT NOT NULL CHECK(member_role IN('teacher','student')),created_at INTEGER NOT NULL,UNIQUE(class_id,user_id));
CREATE TABLE IF NOT EXISTS test_classes(test_id INTEGER NOT NULL REFERENCES tests(id) ON DELETE CASCADE,class_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,PRIMARY KEY(test_id,class_id));
CREATE TABLE IF NOT EXISTS question_bank(id INTEGER PRIMARY KEY AUTOINCREMENT,story_id INTEGER REFERENCES stories(id) ON DELETE CASCADE,bloom TEXT NOT NULL,section TEXT,type TEXT NOT NULL,question TEXT NOT NULL,answer TEXT,options TEXT,marks INTEGER NOT NULL DEFAULT 1,source TEXT NOT NULL DEFAULT 'teacher',approved INTEGER NOT NULL DEFAULT 0,created_by INTEGER REFERENCES users(id),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS resources(id INTEGER PRIMARY KEY AUTOINCREMENT,story_id INTEGER REFERENCES stories(id) ON DELETE CASCADE,owner_id INTEGER REFERENCES users(id),name TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,storage_path TEXT NOT NULL UNIQUE,resource_type TEXT NOT NULL DEFAULT 'attachment',created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS import_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER REFERENCES users(id),filename TEXT,kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'review',details TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS parent_links(id INTEGER PRIMARY KEY AUTOINCREMENT,parent_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,student_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at INTEGER NOT NULL,UNIQUE(parent_id,student_id));
CREATE TABLE IF NOT EXISTS story_reads(id INTEGER PRIMARY KEY AUTOINCREMENT,story_id INTEGER NOT NULL REFERENCES stories(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,read_at INTEGER NOT NULL,UNIQUE(story_id,user_id));
CREATE TABLE IF NOT EXISTS rewards(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,points INTEGER NOT NULL DEFAULT 0,streak INTEGER NOT NULL DEFAULT 0,badges TEXT NOT NULL DEFAULT '[]',updated_at INTEGER NOT NULL,UNIQUE(user_id));
CREATE TABLE IF NOT EXISTS announcements(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,body TEXT NOT NULL,target_role TEXT,target_class_id INTEGER REFERENCES classes(id) ON DELETE CASCADE,expires_at INTEGER,created_by INTEGER REFERENCES users(id),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_usage(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,day TEXT NOT NULL,calls INTEGER NOT NULL DEFAULT 0,input_tokens INTEGER NOT NULL DEFAULT 0,output_tokens INTEGER NOT NULL DEFAULT 0,UNIQUE(user_id,day));
CREATE TABLE IF NOT EXISTS reading_days(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,read_day TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(user_id,read_day));
CREATE TABLE IF NOT EXISTS teacher_comments(id INTEGER PRIMARY KEY AUTOINCREMENT,attempt_id INTEGER NOT NULL UNIQUE REFERENCES attempts(id) ON DELETE CASCADE,teacher_id INTEGER NOT NULL REFERENCES users(id),comment TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempt_history(id INTEGER PRIMARY KEY AUTOINCREMENT,old_attempt_id INTEGER NOT NULL,test_id INTEGER NOT NULL REFERENCES tests(id),user_id INTEGER NOT NULL REFERENCES users(id),answers TEXT,got INTEGER,by_level TEXT,status TEXT NOT NULL,started_at INTEGER,finished_at INTEGER,teacher_comment TEXT,archived_at INTEGER NOT NULL,archived_by INTEGER REFERENCES users(id),reason TEXT NOT NULL DEFAULT 'retake');
CREATE TABLE IF NOT EXISTS login_rate_limits(bucket TEXT PRIMARY KEY,attempts INTEGER NOT NULL,window_start INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS schema_migrations(name TEXT PRIMARY KEY,applied_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS ix_stories_level_status ON stories(level,status); CREATE INDEX IF NOT EXISTS ix_class_members_user ON class_members(user_id); CREATE INDEX IF NOT EXISTS ix_parent_links_parent ON parent_links(parent_id); CREATE INDEX IF NOT EXISTS ix_resources_story ON resources(story_id);
INSERT OR IGNORE INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Kind Farmer','P.1','A farmer named Kato had a small garden. One day, he saw a thirsty bird. He put water in a small dish. The bird drank and flew away. Kato smiled.','A farmer helps a thirsty bird.','A garden in a village','One sunny morning','["Kato: gave water to a thirsty bird"]','["Kato saw a thirsty bird","He put water in a dish","The bird drank and flew away"]','Kindness','Storybook School editorial team','English','Original school-created content','Storybook School','published',(strftime('%s','now')*1000),(strftime('%s','now')*1000) WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Kind Farmer' AND level='P.1');
INSERT OR IGNORE INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'Amina Shares Her Mangoes','P.1','Amina had two ripe mangoes. Her friend Musa had none. Amina cut one mango into two pieces. They sat under a tree and ate together.','Amina shares a mango with Musa.','Under a mango tree','One afternoon','["Amina: shared her mango","Musa: enjoyed the mango"]','["Amina had two mangoes","Musa had none","Amina shared one mango"]','Sharing','Storybook School editorial team','English','Original school-created content','Storybook School','published',(strftime('%s','now')*1000),(strftime('%s','now')*1000) WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='Amina Shares Her Mangoes' AND level='P.1');
INSERT OR IGNORE INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Missing School Bag','P.2','Peter could not find his school bag. He looked near the door and under his bed. His sister Sarah found it behind the chair. Peter thanked her and packed his books.','Peter finds his missing school bag with help from Sarah.','Peter’s home','In the morning','["Peter: looked for his bag","Sarah: found the bag"]','["Peter could not find his bag","He searched near the door","Sarah found it behind a chair","Peter thanked her"]','Being organised','Storybook School editorial team','English','Original school-created content','Storybook School','published',(strftime('%s','now')*1000),(strftime('%s','now')*1000) WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Missing School Bag' AND level='P.2');
INSERT OR IGNORE INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Helpful Neighbour','P.2','Nabirye was carrying a basket of sweet potatoes. The basket became too heavy. Her neighbour, Okello, offered to help. They carried it to her home. Nabirye thanked him.','A neighbour helps Nabirye carry a heavy basket.','A village path','One market day','["Nabirye: carried sweet potatoes","Okello: helped his neighbour"]','["Nabirye carried a basket","The basket became heavy","Okello helped her home"]','Cooperation','Storybook School editorial team','English','Original school-created content','Storybook School','published',(strftime('%s','now')*1000),(strftime('%s','now')*1000) WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Helpful Neighbour' AND level='P.2');
INSERT OR IGNORE INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Clean Water Project','P.3','Pupils at Bright Primary School noticed rubbish near their water source. Their teacher guided them to organise a clean-up. They collected litter, placed it in bins and made signs asking people to keep the area clean. Soon the water point looked better.','Pupils work together to protect their water source.','A school and nearby water point','During a school week','["The pupils: organised a clean-up","Their teacher: guided the activity"]','["Pupils saw rubbish near the water","The teacher guided a clean-up","They collected litter","They made reminder signs"]','Care for the environment','Storybook School editorial team','English','Original school-created content','Storybook School','published',(strftime('%s','now')*1000),(strftime('%s','now')*1000) WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Clean Water Project' AND level='P.3');
INSERT OR IGNORE INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Lost Calf','P.4','When a young calf failed to return to the kraal, Atim and her cousin Joel followed its hoofprints. They found it caught in a loose fence near the stream. Joel held the fence open while Atim guided the calf through. They informed their grandmother and repaired the fence together.','Atim and Joel find a calf and prevent it from getting lost again.','A family farm near a stream','Late afternoon','["Atim: followed hoofprints","Joel: helped free the calf","Grandmother: advised them"]','["The calf did not return","The children followed hoofprints","They found it by a fence","They freed it and told their grandmother","They repaired the fence"]','Responsibility and teamwork','Storybook School editorial team','English','Original school-created content','Storybook School','published',(strftime('%s','now')*1000),(strftime('%s','now')*1000) WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Lost Calf' AND level='P.4');
INSERT OR IGNORE INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Seedling That Survived','P.5','During a long dry spell, Sanyu noticed that the seedlings behind the classroom were wilting. She suggested using water left after washing vegetables. Her classmates agreed to collect it in a clean container. They watered the seedlings carefully and covered the soil with dry grass to reduce evaporation. After several days, new leaves appeared.','Learners save seedlings by reusing suitable water and protecting the soil.','A school garden','During a dry season','["Sanyu: suggested reusing suitable water","Classmates: cared for the seedlings"]','["The seedlings began to wilt","Sanyu suggested reusing water","Pupils collected the water","They watered and mulched the soil","New leaves appeared"]','Resourcefulness and conservation','Storybook School editorial team','English','Original school-created content','Storybook School','published',(strftime('%s','now')*1000),(strftime('%s','now')*1000) WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Seedling That Survived' AND level='P.5');
INSERT OR IGNORE INTO stories(title,level,story,summary,setting,time_period,characters,events,lesson,author,language,licence,source_name,status,created_at,updated_at) SELECT 'The Honest Market Seller','P.6','At the weekly market, Mugisha noticed that a customer had paid more than the price of the vegetables. The market was crowded, and nobody else had noticed the mistake. Mugisha called the customer back and returned the extra money. The customer thanked him, while another trader praised his honesty. Mugisha explained that trust was more valuable than a small extra payment.','Mugisha returns extra money and earns the trust of customers.','A busy village market','On market day','["Mugisha: returned extra money","Customer: thanked the seller","Another trader: praised his honesty"]','["A customer paid too much","Mugisha noticed the mistake","He called the customer back","He returned the extra money","The customer thanked him"]','Honesty builds trust','Storybook School editorial team','English','Original school-created content','Storybook School','published',(strftime('%s','now')*1000),(strftime('%s','now')*1000) WHERE NOT EXISTS (SELECT 1 FROM stories WHERE title='The Honest Market Seller' AND level='P.6');
INSERT OR IGNORE INTO schema_migrations(name,applied_at) VALUES('storybook-upgrade-001',strftime('%s','now')*1000);
INSERT OR IGNORE INTO classes(name,level,academic_year,created_at) VALUES('P.1','P.1',strftime('%Y','now'),strftime('%s','now')*1000),('P.2','P.2',strftime('%Y','now'),strftime('%s','now')*1000),('P.3','P.3',strftime('%Y','now'),strftime('%s','now')*1000),('P.4','P.4',strftime('%Y','now'),strftime('%s','now')*1000),('P.5','P.5',strftime('%Y','now'),strftime('%s','now')*1000),('P.6','P.6',strftime('%Y','now'),strftime('%s','now')*1000);
COMMIT;
PRAGMA foreign_keys=ON;
